from lib import *
FV="Portions de fruits et légumes"
def fv(n): return (FV,f"Portions de fruits et légumes par portion : {n}")
FZ="Instructions de congélation : "
recs=[
R(7183658,"Spaghetti bolognaise",
"Beaucoup de légumes et de lentilles font de ce classique familial très apprécié une version plus saine.",
"6","337 g",
["2 cuillères à café d'huile de colza","2 oignons moyens, finement hachés","500 g de bœuf haché maigre","1 carotte, coupée en petits dés","1 poivron jaune, finement haché","1 courgette, coupée en petits dés","2 à 4 gousses d'ail, écrasées","1 cuillère à café bombée de basilic séché","2 cuillères à café bombées d'origan séché","1 petite pincée de flocons de piment","1 cube de bouillon de bœuf faible en sel","1 boîte de 800 g de tomates hachées","1 cuillère à soupe de concentré de tomate","1 boîte de 400 g de lentilles du Puy, égouttées","10 g de persil fraîchement haché","400 g de spaghettis de blé entier","1 bon tour de moulin de poivre noir","6 feuilles de basilic fraîchement déchirées, pour garnir"],
["Faites chauffer l'huile dans une casserole et faites cuire doucement les oignons jusqu'à ce qu'ils commencent à dorer, en remuant régulièrement.","Ajoutez le bœuf et faites cuire 8 à 10 minutes, en défaisant les grumeaux de bœuf avec une cuillère en bois.","Ajoutez la carotte, le poivron jaune et la courgette et poursuivez la cuisson doucement encore 5 minutes, en remuant toujours régulièrement.","Ajoutez l'ail, les herbes et les flocons de piment et remuez 1 minute. Ajoutez le cube de bouillon, puis les tomates et le concentré de tomate.","Portez à léger frémissement, couvrez et faites cuire 15 minutes, en remuant de temps en temps et en ajoutant un peu d'eau si trop de liquide s'évapore et que ça commence à attacher.","Pendant ce temps, faites cuire les spaghettis selon les instructions du paquet.","Incorporez les lentilles et le persil haché à la sauce, puis faites cuire 5 minutes.","Ajoutez un tour de moulin de poivre noir, saupoudrez de basilic et servez avec les spaghettis de blé entier.","Saupoudrez de copeaux de parmesan, si vous le souhaitez, pour servir."],
["Vous pouvez utiliser de la dinde hachée ou du porc haché pour cette sauce.","Idéal à cuisiner en grande quantité, puis à congeler en portions.",fv(3)]),
R(7185004,"Cari de poulet et de lentilles",
"L'une de nos recettes les plus populaires, ce cari est une excellente façon d'utiliser des restes de poulet et les produits de base du garde-manger. Il est aussi idéal si vous avez un budget serré.",
"4","271 g",
["1 cuillère à café de graines de cumin moulues","1 cuillère à café de graines de coriandre","1 cuillère à soupe d'huile de colza","2 oignons, finement tranchés","4 gousses d'ail, finement tranchées","3 cm de gingembre frais, finement haché","1 à 3 piments verts, fendus","400 g de hauts de cuisse de poulet, coupés en bouchées","1/2 cuillère à café de piment en poudre","1 cuillère à café de garam masala","1 cuillère à café de curcuma en poudre","le jus de 1 citron","1 boîte de 400 g de tomates hachées","150 g de lentilles rouges"],
["Mettez les graines de cumin et de coriandre dans une casserole sèche et faites-les griller 1 à 2 minutes. Ajoutez l'huile et les oignons. Faites cuire 5 minutes, en remuant régulièrement, jusqu'à ce qu'ils soient dorés.","Ajoutez l'ail, le gingembre, les piments verts et les morceaux de poulet et faites cuire encore 2 à 3 minutes, en remuant régulièrement.","Ajoutez le piment en poudre, le garam masala et le curcuma en poudre avec le jus de citron, les tomates et 500 ml d'eau.","Portez à ébullition, mélangez bien, réduisez le feu et laissez mijoter 15 minutes, en remuant régulièrement.","Ajoutez les lentilles et laissez mijoter encore 15 minutes, en remuant régulièrement, jusqu'à ce qu'elles soient cuites."],
["Si vous n'avez pas toutes ces épices sous la main, vous pouvez utiliser votre poudre ou pâte de cari préférée.",FZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur et réchauffez jusqu'à ce que ce soit bien chaud à cœur.",fv(3)]),
R(7186194,"Soupe crémeuse aux asperges",
"Une savoureuse version sans produits laitiers préparée avec du lait de soja.",
"2","346 g",
["15 g de tartinade sans produits laitiers","1 petit oignon, finement haché","10 pointes d'asperges, hachées","25 g de farine nature","450 ml de bouillon de légumes réduit en sel","150 ml de lait de soja non sucré","poivre noir fraîchement moulu"],
["Faites chauffer la tartinade dans une casserole moyenne, ajoutez l'oignon et les asperges et faites revenir 2 à 3 minutes, jusqu'à ce que le tout commence à ramollir.","Ajoutez la farine et faites cuire encore 1 minute.","Incorporez graduellement le bouillon, portez à ébullition et laissez mijoter 10 minutes, jusqu'à ce que les asperges soient bien cuites, en gardant quelques pointes d'asperges pour le service.","Ajoutez le lait, portez presque à ébullition, puis versez dans un mélangeur ou un robot culinaire et mixez jusqu'à consistance lisse.","Assaisonnez de beaucoup de poivre noir et garnissez des pointes d'asperges."],
["Servez avec du pain croustillant ou des rôties.",fv(1)]),
R(7190087,"Nasi goreng avec légumes marinés",
"De la dinde effilochée avec beaucoup de légumes, des œufs, des oignons verts et du piment.",
"6","372 g",
["15 cm de concombre, finement tranché puis haché","1 oignon rouge, finement tranché","1 carotte, coupée en rubans avec un éplucheur, puis tranchée en lanières","le jus de 1/2 citron","1/3 de cuillère à café d'édulcorant granulé","2 cuillères à café d'huile de colza","2 œufs, légèrement battus","2 oignons, finement tranchés","500 g de lanières de dinde pour sauté","1 poivron rouge, finement tranché","2 gousses d'ail, tranchées","1 piment rouge, haché","160 g de chou de Savoie, émincé","4 oignons verts, hachés","1 cuillère à soupe bombée de pâte de nasi goreng","160 g de petits pois surgelés, décongelés","480 g de riz basmati cuit (240 g non cuit)"],
["Mélangez tous les ingrédients des légumes marinés, couvrez, puis réservez en mélangeant de temps en temps.","Mettez une cuillère à café d'huile dans une poêle antiadhésive, puis ajoutez les œufs et faites cuire 30 à 60 secondes pour faire une omelette mince en forme de crêpe. Retirez de la poêle, roulez, puis réservez.","Ajoutez une autre cuillère à café d'huile dans la poêle, ajoutez les oignons tranchés et faites cuire 4 à 5 minutes, en remuant régulièrement. Ajoutez les lanières de dinde et le poivron rouge, puis faites cuire encore 4 minutes.","Ajoutez l'ail, le piment, le chou et les oignons verts, puis faites cuire 3 minutes. Incorporez la pâte de nasi goreng et mélangez bien, en ajoutant un filet d'eau si ça commence à attacher.","Incorporez le riz cuit et remuez régulièrement 4 à 5 minutes, jusqu'à ce que ce soit bien chaud. Mettez dans un bol de service, garnissez d'omelette tranchée et servez avec les légumes marinés."],
["Ne conservez pas le riz cuit plus de 24 heures au réfrigérateur. Refroidissez-le toujours complètement dès que possible.","Vous pouvez utiliser du poulet ou du porc à la place de la dinde.","La pâte de nasi goreng contient des crevettes : ce n'est donc pas végétarien. Remplacez-la par du tofu pour une option végétarienne.",fv(2)]),
R(7194911,"Tourtes au bifteck et aux champignons",
"Ces tourtes au bifteck et aux champignons, mijotées lentement et garnies de pâte, servies avec des feuilles vertes de printemps parfaitement cuites à la vapeur, sont parfaites pour un savoureux repas du soir. Cette recette a été sélectionnée en partenariat avec Slimming World.",
"6","597 g",
["1 oignon, finement tranché","3 branches de céleri, finement tranchées","300 g de champignons châtaigne, coupés en quartiers","3 carottes, pelées et tranchées en rondelles de 2 cm","3 à 4 brins de thym frais","3 gousses d'ail, écrasées","400 g de bœuf maigre à ragoût, gras visible retiré, coupé en morceaux de 2 cm","2 boîtes de 400 g de haricots cannellini, égouttés et rincés","1 litre de bouillon de bœuf faible en sel","1 cuillère à soupe de sauce Worcestershire","150 g de pâte feuilletée à teneur réduite en gras","1 jaune d'œuf, battu","500 g de verts de printemps, émincés, pour servir"],
["Préchauffez votre four à 160 °C/chaleur tournante 140 °C/thermostat 3. Mettez tous les ingrédients, sauf la pâte, le jaune d'œuf et les verts de printemps, dans une grande cocotte allant sur le feu et assaisonnez de poivre. Portez à frémissement sur la cuisinière, puis couvrez et faites cuire au four 2 heures.","Retirez le couvercle. Remuez bien et remettez au four, à découvert, encore 1 heure 30 minutes, en ajoutant les haricots pendant les 20 dernières minutes. Pendant ce temps, découpez 12 formes de champignons dans la pâte, ne pesant pas plus de 12.5 g chacune, ou coupez la pâte en 6 carrés de 25 g. Tapissez une grande plaque de cuisson de papier sulfurisé et déposez les formes de pâte dessus. Badigeonnez de jaune d'œuf et réfrigérez jusqu'au moment voulu.","Sortez la cocotte du four, couvrez et placez à votre feu le plus doux sur la cuisinière pour garder au chaud. Augmentez le four à 220 °C/chaleur tournante 200 °C/thermostat 7 et faites cuire la pâte 20 à 25 minutes, jusqu'à ce qu'elle soit gonflée et dorée. Lorsque la pâte est presque prête, faites cuire les verts de printemps à la vapeur 2 à 3 minutes.","Répartissez le mélange de bœuf entre 6 bols, en retirant les brins de thym, puis répartissez les formes de pâte par-dessus. Servez avec les verts de printemps."],
["Les valeurs nutritionnelles incluent la suggestion de service.",fv(3)]),
R(7195577,"Truite chinoise à la vapeur",
"La cuisson à la vapeur est une façon saine et traditionnelle de cuisiner le poisson.",
"2","264 g",
["4 filets de truite arc-en-ciel, préparés (environ 100 g chacun)","1 cuillère à soupe d'huile de sésame","1 cuillère à soupe de sauce soya réduite en sel","le zeste râpé et le jus de 1 lime","2 gousses d'ail, tranchées","1 morceau de gingembre de 2.5 cm, râpé","1 botte d'oignons verts, tranchés"],
["Placez une feuille de papier sulfurisé dans un grand cuit-vapeur et déposez le poisson dessus.","Mélangez tous les ingrédients restants et versez-les à la cuillère sur le poisson.","Couvrez avec le couvercle et faites cuire à la vapeur 6 à 8 minutes, ou jusqu'à ce que le poisson soit cuit.","Servez avec des légumes sautés, des nouilles ou du riz."],
["Si vous n'avez pas de cuit-vapeur, enveloppez le poisson dans du papier sulfurisé et placez-le sur une grille au-dessus d'une plaque de cuisson. Ajoutez un peu d'eau bouillante dans la plaque et couvrez de papier d'aluminium. Faites ensuite cuire au four à 200 °C/thermostat 6, pendant 8 à 10 minutes.","Vous pouvez cuisiner n'importe quel plat avec cette méthode, mais si vous utilisez du poisson entier ou des darnes épaisses, vous devrez augmenter le temps de cuisson.",fv(0)]),
R(7197806,"Mini crêpes aux bleuets",
"Commencez la journée avec cette version plus saine d'un petit-déjeuner américain classique.",
"10","72 g",
["200 g de farine de blé entier","1 cuillère à café de levure chimique","1 œuf moyen, battu","250 ml de lait écrémé","1 cuillère à café d'extrait de vanille","200 g de bleuets frais","2 cuillères à café d'huile de tournesol","1 cuillère à café de sucre extra-fin (facultatif)"],
["Mélangez la farine et la levure chimique dans un bol.","Dans un autre bol, battez ensemble l'œuf, le lait et l'extrait de vanille.","Creusez un puits au centre de la farine, puis incorporez graduellement le mélange d'œuf et de lait en remuant jusqu'à obtenir une pâte lisse. Idéalement, laissez reposer la pâte quelques minutes avant la cuisson.","Écrasez légèrement la moitié des bleuets à la fourchette et incorporez-les à la pâte, avec les bleuets restants (entiers).","Mettez un peu d'huile dans une poêle antiadhésive, puis versez la pâte dans la poêle, 1 cuillère à soupe à la fois, pour former de petites crêpes, en veillant à ce que les bleuets soient uniformément répartis.","Faites cuire les crêpes à feu moyen 2 à 3 minutes, puis retournez-les et faites cuire encore 2 minutes. Les crêpes sont prêtes à être retournées lorsque vous voyez des bulles apparaître à la surface. Saupoudrez d'un peu de sucre avant de servir, le cas échéant. Servez avec du yogourt non sucré ou de la crème fraîche non sucrée, si vous le souhaitez."],
["Vous devriez pouvoir cuire 3 à 4 crêpes à la fois, selon la taille de la poêle, mais il est conseillé de ne cuire qu'une seule crêpe d'abord pour vérifier que la poêle n'est ni trop chaude ni trop froide.","Gardez la première fournée de crêpes au chaud en les plaçant sur une assiette au-dessus d'une casserole d'eau qui frémit doucement.",FZ+"décongelez 2 heures, ou décongelez/réchauffez au micro-ondes ou dans un four modéré.",fv(0)]),
R(7199003,"Gâteau au chocolat, aux amandes et aux petits fruits",
"Un excellent centre de table pour votre goûter de l'après-midi.",
"8","113 g",
["1 cuillère à café d'huile de colza (pour le moule à gâteau)","50 g de farine de blé entier","50 g de farine nature","15 g de fécule de maïs","1 cuillère à café de levure chimique","15 g de poudre de cacao","4 œufs moyens, séparés","1 cuillère à soupe de yogourt grec à 0 % de matières grasses","4 cuillères à soupe d'édulcorant granulé","2 cuillères à café d'extrait naturel d'amande",("Pour le nappage","200 g de quark sans gras (fromage à la crème)"),("Pour le nappage","1 cuillère à soupe d'édulcorant granulé"),("Pour le nappage","175 g de fraises fraîches, tranchées"),("Pour le nappage","125 g de framboises fraîches")],
["Préchauffez le four à 190 °C/thermostat 5 et huilez légèrement un moule à gâteau de 20 cm.","Tamisez la farine de blé entier, la farine nature, la fécule de maïs, la levure chimique et la poudre de cacao dans un bol. (Le son de la farine de blé entier ne passera pas dans le tamis : remettez-le simplement dans le bol.)","Dans un autre bol, mettez les jaunes d'œufs, le yogourt, l'édulcorant et l'extrait d'amande, et battez bien.","Dans un autre bol, battez les blancs d'œufs jusqu'à ce qu'ils forment des pics fermes.","Incorporez graduellement les ingrédients secs et le mélange de jaunes d'œufs et de yogourt, puis incorporez délicatement les blancs d'œufs.","Versez immédiatement le mélange dans le moule huilé et faites cuire au four 20 à 25 minutes, puis sortez du four et laissez refroidir sur une grille.","Pendant ce temps, préparez le nappage en incorporant 1 cuillère à soupe d'édulcorant au quark et en mélangeant bien, puis laissez au réfrigérateur jusqu'au moment de garnir le gâteau.","Lorsque le gâteau est refroidi, couvrez-le de quark sucré et garnissez de fraises et de framboises fraîches."],
["Les blancs d'œufs battus rendent le gâteau plus léger : veillez donc à ne pas trop mélanger, car votre gâteau pourrait devenir un peu lourd (mais il aura quand même bon goût !)","Lorsque vous incorporez les blancs d'œufs au mélange du gâteau, faites-le délicatement pour garder les bulles d'air emprisonnées à l'intérieur.","Assurez-vous que le gâteau est complètement refroidi avant d'ajouter le nappage.","Tous les fruits d'été conviennent bien. Essayez d'ajouter des bleuets, ou vous pouvez utiliser des tranches de pêche ou d'abricot frais."]),
R(7200396,"Mini muffins au maïs et au parmesan",
"Ils sont excellents comme collations ou dans un lunch à emporter.",
"48","23 g",
["250 g de farine de blé entier","250 g de polenta fine","1 cuillère à soupe de levure chimique","1 cuillère à café de paprika","350 ml de lait demi-écrémé","75 g de tartinade à base d'huile végétale, fondue","2 œufs, battus","2 cuillères à café de romarin frais, haché","2 cuillères à soupe de parmesan frais, râpé"],
["Préchauffez le four à 200 ºC/thermostat 6. Graissez légèrement des moules à mini muffins. Le mélange donnera 48 mini muffins : vous devrez donc peut-être réutiliser les moules (ou vous pouvez faire environ 18 gros muffins, si vous préférez).","Dans un bol, tamisez ensemble la farine, la polenta, la levure chimique et le paprika.","Mélangez le lait, la tartinade et les œufs dans un autre bol avant de les incorporer au mélange de farine. Ajoutez le romarin et mélangez.","Versez à la cuillère dans les moules à muffins et saupoudrez d'un peu de parmesan.","Faites cuire au four 8 à 10 minutes, jusqu'à ce qu'ils soient dorés. Laissez refroidir et servez."],
["Pour une version végétarienne, essayez d'ajouter des tomates séchées hachées.","Également délicieux avec d'autres herbes, comme l'origan ou le thym.",FZ+"peut être congelé une fois cuit. Décongelez 2 heures. Pour servir, décongelez/réchauffez au micro-ondes ou dans un four modéré.",fv(0)]),
R(7201713,"Farce à la sauge, à l'oignon et à la patate douce",
"Un classique rapide et facile avec une touche originale.",
"6","77 g",
["2 gros oignons, grossièrement hachés","2 cuillères à café d'huile de colza","1 pincée de poivre","1 cuillère à café de sauge séchée","1 tranche de pain de blé entier, en chapelure","100 g de patate douce en purée"],
["Mettez les oignons dans une casserole avec l'huile de colza et faites cuire doucement 6 à 7 minutes, jusqu'à ce qu'ils soient ramollis et commencent à dorer.","Ajoutez le poivre et la sauge. Ajoutez ensuite la chapelure, la patate douce et 200 ml d'eau de cuisson des pommes de terre.","Mélangez bien, placez le mélange dans un plat allant au four légèrement huilé et faites cuire au four 20 minutes, jusqu'à ce que le dessus soit doré."],
["Si vous n'aimez pas la sauge, essayez d'ajouter une cuillère à soupe de persil fraîchement haché et une cuillère à café de thym séché, ou utilisez de l'origan ou de l'estragon à la place.",FZ+"congelez en portions, puis décongelez au réfrigérateur, ou au micro-ondes, et réchauffez jusqu'à ce que ce soit bien chaud.",fv(0)]),
]
save(7,recs)
